// SALUTE -> CoT converter
const d = (msg.req && msg.req.body && Object.keys(msg.req.body).length) ? msg.req.body : msg.payload;
const respond = (code, body) => msg.res ? { res: msg.res, _msgid: msg._msgid, statusCode: code, payload: body } : null;

// ---- validate ----
const errors = [];
const need = ["callsign", "size", "activity", "unit", "equipment"];
need.forEach(k => { if (!d || !String(d[k] || "").trim()) errors.push(k + " is required"); });
const lat = parseFloat(d && d.lat), lon = parseFloat(d && d.lon);
if (!(lat >= -90 && lat <= 90)) errors.push("lat must be -90..90");
if (!(lon >= -180 && lon <= 180)) errors.push("lon must be -180..180");
const affil = (d && d.affiliation) || "a-u-G";
if (!/^a-[uhsnf]-G$/.test(affil)) errors.push("invalid affiliation");
if (errors.length) { node.warn(errors.join("; ")); return [null, respond(400, { ok: false, errors })]; }

// ---- helpers ----
const esc = s => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;").replace(/'/g, "&apos;");
const uuid = () => "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, c => {
    const r = Math.random() * 16 | 0; return (c === "x" ? r : (r & 0x3 | 0x8)).toString(16); });

const mission = String(d.mission || env.get("DEFAULT_MISSION") || "").trim();
const wantPkg = !!d.package && d.package !== "false";
const now = new Date();
const stale = new Date(now.getTime() + (parseInt(d.staleMinutes) || 60) * 60000);
let obs = d.time ? new Date(d.time) : now;
if (isNaN(obs)) obs = now;

const uid = "SALUTE-" + uuid();
const callsign = "SALUTE-" + esc(String(d.callsign).trim());

const opt = k => String((d && d[k]) || "").trim();
const extra =
    (opt("habits") ? "H (Habits): " + opt("habits") + "\n" : "") +
    (opt("intentions") ? "I (Intentions): " + opt("intentions") + "\n" : "") +
    (opt("morale") ? "M (Morale): " + opt("morale") + "\n" : "");
const extraAttrs = ["habits", "intentions", "morale"]
    .filter(k => opt(k)).map(k => " " + k + '="' + esc(opt(k)) + '"').join("");

const remarks =
    "SALUTE REPORT\n" +
    "S (Size): " + d.size + "\n" +
    "A (Activity): " + d.activity + "\n" +
    "L (Location): " + lat.toFixed(6) + ", " + lon.toFixed(6) + "\n" +
    "U (Unit): " + d.unit + "\n" +
    "T (Time): " + obs.toISOString() + "\n" +
    "E (Equipment): " + d.equipment + "\n" +
    extra +
    "Reported by: " + d.callsign;

const xml =
    '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>' +
    '<event version="2.0" uid="' + uid + '" type="' + affil + '" how="h-e"' +
    ' time="' + now.toISOString() + '" start="' + now.toISOString() + '" stale="' + stale.toISOString() + '">' +
    '<point lat="' + lat + '" lon="' + lon + '" hae="9999999.0" ce="9999999.0" le="9999999.0"/>' +
    '<detail>' +
    '<contact callsign="' + callsign + '"/>' +
    (mission ? '<marti><dest mission="' + esc(mission) + '"/></marti>' : '') +
    '<remarks source="' + esc(d.callsign) + '">' + esc(remarks) + '</remarks>' +
    '<salute size="' + esc(d.size) + '" activity="' + esc(d.activity) + '" unit="' + esc(d.unit) +
        '" time="' + obs.toISOString() + '" equipment="' + esc(d.equipment) + '"' + extraAttrs + '/>' +
    '</detail></event>';

// ---- keep history ----
const hist = global.get("salute_reports") || [];
hist.unshift({ uid, callsign: d.callsign, received: now.toISOString(), affiliation: affil,
    size: d.size, activity: d.activity, lat, lon, unit: d.unit, time: obs.toISOString(), equipment: d.equipment,
    habits: opt("habits"), intentions: opt("intentions"), morale: opt("morale") });
global.set("salute_reports", hist.slice(0, 200));

const pkgName = callsign + "_" + obs.toISOString().replace(/[-:]/g, "").slice(0, 15) + "Z";
const out = { ok: true, uid, mission: mission || null };
if (wantPkg) out.packageUrl = "salute/package/" + uid;
return [
    { payload: xml },
    respond(200, out),
    wantPkg ? { payload: xml, uid, mission, pkgName, callsign } : null
];

// Build a Mission Package (data package) zip: MANIFEST/manifest.xml + <uid>/<uid>.cot
const crcT = (() => { const t = []; for (let n = 0; n < 256; n++) { let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xEDB88320 ^ (c >>> 1) : c >>> 1; t[n] = c >>> 0; } return t; })();
const crc32 = b => { let c = 0xFFFFFFFF; for (let i = 0; i < b.length; i++) c = crcT[(c ^ b[i]) & 0xFF] ^ (c >>> 8);
    return (c ^ 0xFFFFFFFF) >>> 0; };

function zip(files) {                       // minimal "stored" zip writer, no dependencies
    const d = new Date();
    const dt = ((d.getFullYear() - 1980) << 9 | (d.getMonth() + 1) << 5 | d.getDate()) & 0xFFFF;
    const tm = (d.getHours() << 11 | d.getMinutes() << 5 | (d.getSeconds() >> 1)) & 0xFFFF;
    const parts = [], central = []; let off = 0;
    for (const f of files) {
        const name = Buffer.from(f.name), crc = crc32(f.data), sz = f.data.length;
        const lh = Buffer.alloc(30);
        lh.writeUInt32LE(0x04034b50, 0); lh.writeUInt16LE(20, 4); lh.writeUInt16LE(0x0800, 6); lh.writeUInt16LE(0, 8);
        lh.writeUInt16LE(tm, 10); lh.writeUInt16LE(dt, 12); lh.writeUInt32LE(crc, 14);
        lh.writeUInt32LE(sz, 18); lh.writeUInt32LE(sz, 22); lh.writeUInt16LE(name.length, 26);
        parts.push(lh, name, f.data);
        const ch = Buffer.alloc(46);
        ch.writeUInt32LE(0x02014b50, 0); ch.writeUInt16LE(20, 4); ch.writeUInt16LE(20, 6); ch.writeUInt16LE(0x0800, 8);
        ch.writeUInt16LE(tm, 12); ch.writeUInt16LE(dt, 14); ch.writeUInt32LE(crc, 16);
        ch.writeUInt32LE(sz, 20); ch.writeUInt32LE(sz, 24); ch.writeUInt16LE(name.length, 28); ch.writeUInt32LE(off, 42);
        central.push(ch, name);
        off += 30 + name.length + sz;
    }
    const cd = Buffer.concat(central), e = Buffer.alloc(22);
    e.writeUInt32LE(0x06054b50, 0); e.writeUInt16LE(files.length, 8); e.writeUInt16LE(files.length, 10);
    e.writeUInt32LE(cd.length, 12); e.writeUInt32LE(off, 16);
    return Buffer.concat([...parts, cd, e]);
}
const esc = s => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

const uid = msg.uid;
const zipName = msg.pkgName + ".zip";
const manifest =
    '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>' +
    '<MissionPackageManifest version="2"><Configuration>' +
    '<Parameter name="uid" value="' + esc(uid) + '"/>' +
    '<Parameter name="name" value="' + esc(zipName) + '"/>' +
    '<Parameter name="onReceiveImport" value="true"/>' +
    '<Parameter name="onReceiveDelete" value="true"/>' +
    '</Configuration><Contents>' +
    '<Content ignore="false" zipEntry="' + esc(uid) + '/' + esc(uid) + '.cot"/>' +
    '</Contents></MissionPackageManifest>';

const buf = zip([
    { name: "MANIFEST/manifest.xml", data: Buffer.from(manifest) },
    { name: uid + "/" + uid + ".cot", data: Buffer.from(msg.payload) }
]);

// keep the newest 25 packages for manual download
const pk = global.get("salute_packages") || {};
const order = global.get("salute_package_order") || [];
pk[uid] = { name: zipName, buf };
order.push(uid);
while (order.length > 25) delete pk[order.shift()];
global.set("salute_packages", pk);
global.set("salute_package_order", order);

// push to TAK Server only when a mission and API base URL are known
const api = String(env.get("TAK_API") || "").replace(/\/+$/, "");
if (!msg.mission || !api) {
    node.status({ fill: "yellow", shape: "ring", text: "package stored, no upload (mission/TAK_API unset)" });
    return [null, { payload: "package " + zipName + " built, not uploaded" }];
}
const creator = env.get("CREATOR_UID") || "SALUTE-NODERED";
node.status({ fill: "green", shape: "dot", text: "uploading " + zipName });
return [{
    method: "POST",
    url: api + "/Marti/sync/upload?name=" + encodeURIComponent(zipName) +
         "&filename=" + encodeURIComponent(zipName) + "&creatorUid=" + encodeURIComponent(creator),
    headers: { "Content-Type": "application/octet-stream" },
    payload: buf, mission: msg.mission, uid, zipName
}, null];

// Take the content hash returned by the upload and attach it to the mission
if (msg.statusCode !== 200) { node.error("Upload failed, HTTP " + msg.statusCode + ": " + msg.payload, msg); return null; }
let hash = String(msg.payload || "").trim();
try { const j = JSON.parse(hash); hash = j.Hash || j.hash || (j.data && (j.data.Hash || j.data.hash)) || hash; } catch (e) {}
if (!/^[0-9a-fA-F]{64}$/.test(hash)) { node.error("Could not read content hash from upload response: " + hash, msg); return null; }

const api = String(env.get("TAK_API")).replace(/\/+$/, "");
const creator = env.get("CREATOR_UID") || "SALUTE-NODERED";
return {
    method: "PUT",
    url: api + "/Marti/api/missions/" + encodeURIComponent(msg.mission) + "/contents?creatorUid=" + encodeURIComponent(creator),
    headers: { "Content-Type": "application/json" },
    payload: { hashes: [hash] },
    mission: msg.mission, uid: msg.uid, zipName: msg.zipName
};

const p = (global.get("salute_packages") || {})[msg.req.params.uid];
if (!p) { msg.statusCode = 404; msg.headers = { "Content-Type": "text/plain" }; msg.payload = "Package not found (only the newest 25 are kept)"; return msg; }
msg.statusCode = 200;
msg.headers = { "Content-Type": "application/zip", "Content-Disposition": 'attachment; filename="' + p.name + '"' };
msg.payload = p.buf;
return msg;

// Map settings for the form (override with tab env vars)
const c = String(env.get("MAP_CENTER") || "39.5,-98.35").split(",").map(Number);
const ok = c.length === 2 && c.every(Number.isFinite);
return {
    res: msg.res, _msgid: msg._msgid, statusCode: 200,
    headers: { "Content-Type": "application/json", "Cache-Control": "no-store" },
    payload: {
        tileUrl: env.get("TILE_URL") || "https://tile.openstreetmap.org/{z}/{x}/{y}.png",
        attribution: env.get("TILE_ATTRIBUTION") || "&copy; OpenStreetMap contributors",
        lat: ok ? c[0] : 39.5, lon: ok ? c[1] : -98.35,
        zoom: parseInt(env.get("MAP_ZOOM")) || 4
    }
};

// Mission list for the form dropdown (cached 60 s; ?refresh=1 bypasses the cache)
const send = payload => ({ res: msg.res, _msgid: msg._msgid, statusCode: 200,
    headers: { "Content-Type": "application/json", "Cache-Control": "no-store" }, payload });
const api = String(env.get("TAK_API") || "").replace(/\/+$/, "");
if (!api) return [null, send({ ok: false, missions: [], error: "TAK_API not set" })];

const c = global.get("salute_missions_cache");
const force = msg.req && msg.req.query && msg.req.query.refresh;
if (c && !force && Date.now() - c.t < 60000) return [null, send({ ok: true, missions: c.list, cached: true })];

return [{ res: msg.res, _msgid: msg._msgid, method: "GET", url: api + "/Marti/api/missions",
          headers: { "Accept": "application/json" } }, null];

// Turn the TAK Server mission list into plain names for the form
const send = payload => ({ res: msg.res, _msgid: msg._msgid, statusCode: 200,
    headers: { "Content-Type": "application/json", "Cache-Control": "no-store" }, payload });

if (msg.error) { node.warn("Mission list: " + (msg.error.message || msg.error)); return send({ ok: false, missions: [], error: "could not reach TAK Server" }); }
if (msg.statusCode !== 200) { node.warn("Mission list HTTP " + msg.statusCode); return send({ ok: false, missions: [], error: "TAK Server returned HTTP " + msg.statusCode }); }

let list = [];
try {
    const j = typeof msg.payload === "string" ? JSON.parse(msg.payload) : msg.payload;
    const arr = Array.isArray(j) ? j : (j.data || j.missions || []);
    list = arr.map(m => typeof m === "string" ? m : (m && m.name))
              .filter(n => typeof n === "string" && n)
              .sort((a, b) => a.localeCompare(b));
} catch (e) { return send({ ok: false, missions: [], error: "unreadable response" }); }

global.set("salute_missions_cache", { t: Date.now(), list });
return send({ ok: true, missions: list });
